 private void cover(){if(cover!=null){stage.removeView(cover);cover=null;return;}TextView block=new TextView(this);block.setText("اسحب لتحريك التغطية\nاسحب الزاوية لتغيير الحجم");block.setTextColor(Color.WHITE);block.setGravity(Gravity.CENTER);block.setBackgroundColor(Color.rgb(45,51,49));FrameLayout.LayoutParams p=new FrameLayout.LayoutParams(220,220);p.leftMargin=40;p.topMargin=40;stage.addView(block,p);cover=block;block.setOnTouchListener(new View.OnTouchListener(){float x,y;int left,top,w,h;boolean resize;public boolean onTouch(View v,android.view.MotionEvent e){if(locked)return true;FrameLayout.LayoutParams a=(FrameLayout.LayoutParams)v.getLayoutParams();if(e.getAction()==0){x=e.getRawX();y=e.getRawY();left=a.leftMargin;top=a.topMargin;w=a.width;h=a.height;resize=e.getX()>w-60&&e.getY()>h-60;return true;}if(e.getAction()==2){int dx=(int)(e.getRawX()-x),dy=(int)(e.getRawY()-y);if(resize){a.width=Math.max(80,Math.min(stage.getWidth()-left,w+dx));a.height=Math.max(80,Math.min(stage.getHeight()-top,h+dy));}else{a.leftMargin=Math.max(0,Math.min(stage.getWidth()-w,left+dx));a.topMargin=Math.max(0,Math.min(stage.getHeight()-h,top+dy));}v.setLayoutParams(a);return true;}return true;}});toast("تغطية يدوية للمشاهدة فقط؛ لا تتتبع الأشخاص");}
 @Override protected void onActivityResult(int request,int result,Intent data){super.onActivityResult(request,result,data);if(request==7204){if(result==RESULT_OK)beginWatch();else{ColabCredentials.clear();watchError("لم يبدأ الفصل السحابي");}return;}if(request!=32||result!=RESULT_OK||data==null||data.getData()==null)return;try{String name="";try(android.database.Cursor c=getContentResolver().query(data.getData(),new String[]{android.provider.OpenableColumns.DISPLAY_NAME},null,null,null)){if(c!=null&&c.moveToFirst())name=c.getString(0);}String ext=name.toLowerCase(Locale.ROOT).endsWith(".vtt")?".vtt":".srt";File f=File.createTempFile("subtitle_",ext,getCacheDir());try(InputStream in=getContentResolver().openInputStream(data.getData());OutputStream out=new FileOutputStream(f)){byte[] b=new byte[8192];int n,total=0;while((n=in.read(b))!=-1){total+=n;if(total>4*1024*1024)throw new IOException("ملف الترجمة كبير جدًا");out.write(b,0,n);}}position=player.getCurrentPosition();resume=clean!=null?clean.wanted():resume||player.getPlayWhenReady();File old=subtitle;subtitle=f;buildPlayer();if(old!=null)old.delete();toast("تم تحميل الترجمة");}catch(Exception e){toast("تعذر فتح الترجمة");}}
 private void music(){
  if(cleanRequested){new AlertDialog.Builder(this).setTitle("الصوت أثناء المشاهدة").setItems(new String[]{"الإبقاء على الصوت المنظّف","تشغيل الصوت الأصلي","إيقاف الفصل وتشغيل الصوت الأصلي"},(d,n)->{if(n==2){if(watchJob!=null&&!watchJob.clean.done)startService(new Intent(this,WatchMusicService.class).setAction("cancel").putExtra("job",watchJob.id));else if(legacyClean&&VideoExportService.active)startService(new Intent(this,VideoExportService.class).setAction("cancel"));}if(n>0)originalAudio();}).show();return;}
  if(legacyClean&&cleanSession!=null&&!cleanSession.failed){position=player.getCurrentPosition();resume=player.getPlayWhenReady();cleanRequested=true;attachWatch();return;}
  WatchMusicService.Job existing=WatchMusicService.current;if(existing!=null&&existing.identity.equals(input.identity)&&existing.usable()){watchJob=existing;cleanSession=existing.clean;position=player.getCurrentPosition();resume=player.getPlayWhenReady();cleanRequested=true;attachWatch();return;}
  if(WatchMusicService.busy()){toast("انتظر اكتمال المعالجة الحالية أو أوقفها من الإشعار");return;}
  long duration=player.getDuration();if(duration<=0||duration==C.TIME_UNSET){toast("انتظر تحميل المقطع أولًا");return;}
  chooseWatchStart(Math.max(0,Math.min(player.getCurrentPosition(),duration-100)));
 }
